import React,{useState}from'react';import{createRoot}from'react-dom/client';import{createClient}from'@supabase/supabase-js';import{CalendarDays,MessageCircle,Wrench,Settings,Users,Inbox,ChevronRight,ChevronLeft,Check,Upload,MapPin,Truck,Home as HomeIcon,AlertCircle,Send,ArrowLeft,GripVertical,LogOut,Plus,Link as LinkIcon,Copy,ExternalLink,Power,Share2}from'lucide-react';import'./styles.css';
const U=import.meta.env.VITE_SUPABASE_URL||'',K=import.meta.env.VITE_SUPABASE_ANON_KEY||'',db=U&&K?createClient(U,K):null;
async function apiJson(url:string,options:RequestInit={}){
 const response=await fetch(url,options);
 const type=response.headers.get('content-type')||'';
 const raw=await response.text();
 let payload:any={};
 if(raw&&type.includes('application/json')){try{payload=JSON.parse(raw)}catch{payload={error:'The API returned malformed JSON.'}}}
 else if(raw){payload={error:`The API returned an unexpected response (${response.status}). ${raw.slice(0,120)}`}}
 if(!response.ok)throw new Error(payload.error||`Request failed (${response.status})`);
 return payload;
}
const FALLBACK_S=[['Tune-Up','$50'],['Tube / Tire Installation','$15'],['Tubeless Setup','$25'],['Brake Adjustment','$20'],['Derailleur (Gear) Adjustment','$20'],['Chain Replacement','$15'],['Cable Replacement','$25'],['Wheel Truing','$20'],['Boxed Bike Assembly','$75'],['Other Repairs (Labor Rate)','$60/hour']];
