function useAdminData(resource:string){const[data,setData]=React.useState<any[]>([]),[loading,setLoading]=React.useState(true),[error,setError]=React.useState('');React.useEffect(()=>{setLoading(true);setError('');adminFetch(resource).then(x=>{if(!Array.isArray(x))throw new Error(`${resource} API returned an unexpected response`);setData(x)}).catch(e=>{setData([]);setError(e.message)}).finally(()=>setLoading(false))},[resource]);return{data,setData,loading,error}}
